using Microsoft.ML;
using Microsoft.ML.Data;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var mlContext = new MLContext(seed: 0);

// Load CSV — Churned is "Yes"/"No", so load as string and map to bool Label
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
IDataView dataView = mlContext.Data.LoadFromTextFile<CustomerDataRaw>(
    dataPath, hasHeader: true, separatorChar: ',');

// Map "Yes" → true, "No" → false into a Label column
var yesNoMap = mlContext.Data.LoadFromEnumerable(new[]
{
    new YesNoMapping { Churned = "Yes", Label = true },
    new YesNoMapping { Churned = "No",  Label = false }
});

var pipeline = mlContext.Transforms.Conversion.MapValue(
        "Label", yesNoMap, yesNoMap.Schema["Churned"], yesNoMap.Schema["Label"],
        inputColumnName: nameof(CustomerDataRaw.Churned))
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerDataRaw.Region)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerDataRaw.Age),
        nameof(CustomerDataRaw.Income),
        "RegionEncoded",
        nameof(CustomerDataRaw.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

var model = pipeline.Fit(dataView);

app.MapGet("/", () => "Churn Predictor API — POST to /predict");

app.MapPost("/predict", (CustomerInput input) =>
{
    var predictionEngine = mlContext.Model
        .CreatePredictionEngine<CustomerDataRaw, ChurnPrediction>(model);

    var sample = new CustomerDataRaw
    {
        Age = input.Age,
        Income = input.Income,
        Region = input.Region,
        PurchaseHistory = input.PurchaseHistory,
        Churned = "No" // placeholder; not used for prediction
    };

    var prediction = predictionEngine.Predict(sample);

    return Results.Ok(new
    {
        Churned = prediction.PredictedLabel ? "Yes" : "No",
        Probability = Math.Round(prediction.Probability, 4)
    });
});

app.Run();

// --- Models ---

public class CustomerDataRaw
{
    [LoadColumn(0)] public float Age { get; set; }
    [LoadColumn(1)] public float Income { get; set; }
    [LoadColumn(2)] public string Region { get; set; } = string.Empty;
    [LoadColumn(3)] public float PurchaseHistory { get; set; }
    [LoadColumn(4)] public string Churned { get; set; } = string.Empty;
}

public class YesNoMapping
{
    public string Churned { get; set; } = string.Empty;
    public bool Label { get; set; }
}

public class CustomerInput
{
    public float Age { get; set; }
    public float Income { get; set; }
    public string Region { get; set; } = string.Empty;
    public float PurchaseHistory { get; set; }
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }
    public float Probability { get; set; }
}

